package io.github.hoangtnedu.java;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class SpringTest {
 @Autowired MockMvc mvc;@Autowired StudentService service;
 @Test void homeAboutAndList()throws Exception{mvc.perform(get("/")).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("HoangTN")));mvc.perform(get("/about")).andExpect(status().isOk());mvc.perform(get("/students")).andExpect(status().is3xxRedirection());}
 @Test @org.springframework.security.test.context.support.WithMockUser(roles="ADMIN") void formValidationAndPersistence()throws Exception{String code="SV"+System.nanoTime();mvc.perform(post("/students/save").with(org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf()).param("studentCode","").param("fullName","").param("email","bad").param("className","")).andExpect(status().isOk()).andExpect(model().attributeHasFieldErrors("student","studentCode","fullName","email","className"));mvc.perform(post("/students/save").with(org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf()).param("studentCode",code).param("fullName","Demo").param("email","demo@example.com").param("className","JAVA01")).andExpect(status().is3xxRedirection());assertTrue(service.list("Demo").stream().anyMatch(s->s.getStudentCode().equals(code)));mvc.perform(post("/students/save").with(org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf()).param("studentCode",code).param("fullName","Other").param("email","demo@example.com").param("className","JAVA01")).andExpect(status().isOk()).andExpect(model().attributeHasFieldErrors("student","studentCode"));}
 @Test @org.springframework.security.test.context.support.WithMockUser(roles="USER") void userCannotWriteOrSeeAdminLinks()throws Exception{mvc.perform(get("/students/create")).andExpect(status().isForbidden());mvc.perform(post("/students/save").with(org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf())).andExpect(status().isForbidden());mvc.perform(get("/students")).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString(">THEM<"))));}
 @Test @org.springframework.security.test.context.support.WithMockUser(roles="ADMIN") void missingCsrfRejected()throws Exception{mvc.perform(post("/students/save")).andExpect(status().isForbidden());}
 @Test void loginWorks()throws Exception{mvc.perform(org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestBuilders.formLogin().user("admin").password(System.getenv().getOrDefault("LAB_DEMO_PASSWORD","change-me-local"))).andExpect(org.springframework.security.test.web.servlet.response.SecurityMockMvcResultMatchers.authenticated());}
}